// FDB Sim2, paraphrased: a 'connection' is two in-memory buffers plus a clogging check
function deliver(conn, packet):
  if clogging.disconnected(conn.from, conn.to):
    return                       // dropped: this is what a partition IS here
  delay = rng.next_delay()       // seeded latency
  schedule_at(clock + delay, () => conn.to.inbox.push(packet))

class TransferWorkload(Workload):
    def setup(self, cluster, rng):
        self.accounts = cluster.create_accounts(rng.randint(10, 1000))

    def execution(self, cluster, rng):
        # generative: each run draws a different but seed-reproducible
        # sequence of operations, not a fixed hand-authored script
        for _ in range(rng.randint(100, 10_000)):
            src, dst = rng.sample(self.accounts, 2)
            amount = rng.randint(1, 100)
            cluster.transfer(src, dst, amount)

    def check(self, cluster):
        assert cluster.total_balance() == self.initial_total  # oracle

