# integrated / choice-sequence shrinking: shrink the seed's decision
# stream, not a serialized fault list, so every candidate is guaranteed
# to still be a legal execution of the same generator
def shrink(choices, still_fails):
    best = choices
    for candidate in delta_debug_candidates(best):
        if still_fails(replay(candidate)):
            best = candidate  # keep shrinking from here
    return best

function is_linearizable(history, model):
  # history: list of {op, start_time, end_time, invoked_args, observed_result}
  # try every order consistent with real-time (A before B if A.end < B.start)
  for order in real_time_consistent_permutations(history):
    state = model.initial()
    ok = true
    for op in order:
      (state, expected) = model.apply(state, op.invoked_args)
      if expected != op.observed_result:
        ok = false; break
    if ok:
      return PASS(witness=order)
  return FAIL("no legal sequential order reproduces every observed result")

class ChainIntegrityWorkload(Workload):
  def check(self, cluster):
    # a local, always-on invariant check -- an assertion, not a search
    node = cluster.get(self.head_key)
    seen = set()
    while node is not None:
      assert node.key not in seen, "cycle detected -- isolation was violated"
      seen.add(node.key)
      node = cluster.get(node.next_key) if node.next_key else None
    assert len(seen) == self.expected_length, "chain is broken or truncated"

// crash-stop: gone for good, no recovery path is ever exercised
function crashStop(node):
  node.kill()
  cluster.remove(node)               // membership just shrinks

// crash-recovery: the only kind of fault that runs recovery code at all
function crashRecover(node, rng):
  node.kill()
  simulated_sleep(rng.next_offset()) // down for a seeded interval
  node.restart_from(node.stable_storage)  // WAL replay / snapshot load
  cluster.rejoin(node)

